mapper.select:
select *
from fitian.Wod
where boxCode = #{boxCode}
and wodDate = #{wodDate}
and useYN = "Y"

mapper.update:
    	update fitian.Wod 
    	SET 

			wodScript=#{wodScript},


			wodType=#{wodType},


			wodTitle=#{wodTitle},

 		wodDate=#{wodDate}
    	where boxCode = #{boxCode}
        and wodDate = #{wodDate}
        and useYN = "Y"

	update fitian.Wod 
	SET useYN = "N"
	where boxCode = #{boxCode}
    and wodDate = #{wodDate}

mapper.select:
select testNumber
from fitian.TestTable
where testName = #{test}
